        /// <see cref="gmres{TOp,TPre}"/>'s: no M⁻¹ apply, no separate preconditioned-basis storage.
        /// recycle = 0 disables recycling entirely and is bit-identical to <see cref="gmres{TOp,TPre}"/>.
        ///
