                for (int i = 0; i < m; i++) AV.Add(new floatN(n));
            }
            var H = new floatMxN(m + 1, m, Allocator.Temp, false);
            var cs = new floatN(m);
            var sn = new floatN(m);
            var g = new floatN(m + 1);
            var y = new floatN(m);
            var w = new floatN(n);

            // ---- recycled-subspace state (Temp), fixed max size `recycle`, active prefix `kcur` ----
            UnsafeList<floatN> U = default, C = default;
            floatMxN Ru = default;   // recycle x recycle, active top-left kcur x kcur upper-triangular
            floatMxN Bmat = default; // recycle x m, active kcur x p projection coefficients
            floatN ctr = default;
            floatN zproj = default;
            int kcur = 0;
            if (recycling)
            {
                U = new UnsafeList<floatN>(recycle, Allocator.Temp);
                C = new UnsafeList<floatN>(recycle, Allocator.Temp);
                for (int i = 0; i < recycle; i++) { U.Add(new floatN(n)); C.Add(new floatN(n)); }
                Ru = new floatMxN(recycle, recycle, Allocator.Temp, false);
                Bmat = new floatMxN(recycle, m, Allocator.Temp, false);
                ctr = new floatN(recycle);
                zproj = new floatN(recycle);
