                resnorm = beta;
                if (beta <= thresh) { converged = true; break; }

                float invBeta = (float)1 / beta;
                for (int i = 0; i < n; i++) v0[i] *= invBeta;
                for (int i = 0; i <= m; i++) g[i] = (float)0;
                g[0] = beta;

