                    for (int i = 0; i < j; i++)
                    {
                        float t0 = cs[i] * H[i, j] + sn[i] * H[i + 1, j];
                        H[i + 1, j] = -sn[i] * H[i, j] + cs[i] * H[i + 1, j];
                        H[i, j] = t0;
                    }

                    // New Givens rotation zeroing H[j+1,j].
                    float a0 = H[j, j], b0 = H[j + 1, j];
                    float rr = math.sqrt(a0 * a0 + b0 * b0);
                    float c, s;
                    if (rr > (float)0) { c = a0 / rr; s = b0 / rr; }
                    else { c = (float)1; s = (float)0; }
                    cs[j] = c; sn[j] = s;
                    H[j, j] = rr;
                    H[j + 1, j] = (float)0;

                    float gj = g[j];
                    g[j] = c * gj;
                    g[j + 1] = -s * gj;

                    resnorm = math.abs(g[j + 1]);
                    total++;
                    p = j + 1;

                    if (resnorm <= thresh) { converged = true; break; }
                    if (arnoldiDone) break;
                }

                // Back-substitute H[0..p-1,0..p-1] y = g[0..p-1]; a collapsed pivot is an honest
