                {
                    float sum = g[i];
                    for (int l = i + 1; l < p; l++) sum -= H[i, l] * y[l];
                    float diag = H[i, i];
                    if (math.abs(diag) <= pivotGuard) { breakdown = true; break; }
                    y[i] = sum / diag;
                }
                if (breakdown)
