                        for (int l = i + 1; l < kcur; l++) s -= Ru[i, l] * zproj[l];
                        float diag = Ru[i, i];
                        zproj[i] = math.abs(diag) > pivotGuard ? s / diag : (float)0;
                    }
                    for (int i = 0; i < kcur; i++) x.addScaledInPlace(-zproj[i], U[i]);
