                    var Fmat = new floatMxN(d, d, Allocator.Temp, false);
                    var Gmat = new floatMxN(d, d, Allocator.Temp, false);
                    var Pgram = new floatMxN(d, d, Allocator.Temp, false);

                    for (int ai = 0; ai < d; ai++)
                    {
                        floatN APa = ai < kcurAtEntry ? AU[ai] : AV[ai - kcurAtEntry];
                        floatN Pa = ai < kcurAtEntry ? U[ai] : (flexible ? Zv[ai - kcurAtEntry] : V[ai - kcurAtEntry]);

                        for (int bi = ai; bi < d; bi++)
                        {
                            floatN APbv = bi < kcurAtEntry ? AU[bi] : AV[bi - kcurAtEntry];
                            floatN Pbv = bi < kcurAtEntry ? U[bi] : (flexible ? Zv[bi - kcurAtEntry] : V[bi - kcurAtEntry]);

                            float fval = Blas.dot(APa, APbv);
                            Fmat[ai, bi] = fval; Fmat[bi, ai] = fval;

                            float pval = Blas.dot(Pa, Pbv);
                            Pgram[ai, bi] = pval; Pgram[bi, ai] = pval;
                        }

                        for (int bi = 0; bi < d; bi++)
                        {
                            floatN Pbv = bi < kcurAtEntry ? U[bi] : (flexible ? Zv[bi - kcurAtEntry] : V[bi - kcurAtEntry]);
                            Gmat[ai, bi] = Blas.dot(APa, Pbv);
                        }
                    }

                    var GmatLU = new floatMxN(Gmat, Allocator.Temp);
                    var Xsol = new floatMxN(Fmat, Allocator.Temp);
                    var piv = new Pivot(d, Allocator.Temp);
                    var luInfo = LU.solveInPlace(ref GmatLU, ref piv, ref Xsol);
                    piv.Dispose();
                    GmatLU.Dispose();

                    var evReal = new floatN(d);
                    var evImag = new floatN(d);
                    bool haveEig = false;
                    if (luInfo.Solved)
                    {
                        var eiInfo = Eigen.valuesQRInPlace(ref Xsol, ref evReal, ref evImag);
                        haveEig = eiInfo.status == IterativeSolveStatus.Converged;
                    }

                    float huge = (float)1e30;
                    var keys = new floatN(d);
                    for (int i = 0; i < d; i++)
                    {
                        if (!haveEig) { keys[i] = huge; continue; }
                        float re = evReal[i], im = evImag[i];
                        float imagTol = Consts.floatZeroThreshold * (math.abs(re) + (float)1);
                        keys[i] = math.abs(im) <= imagTol ? math.abs(re) : huge;
                    }

                    int target = math.min(recycle, d);
                    var selIdx = new UnsafeList<int>(math.max(target, 1), Allocator.Temp);
                    for (int sIt = 0; sIt < target; sIt++)
                    {
                        int best = -1;
                        float bestKey = huge;
                        for (int i = 0; i < d; i++)
                            if (keys[i] < bestKey) { bestKey = keys[i]; best = i; }
                        if (best < 0 || bestKey >= huge) break;
                        selIdx.Add(best);
                        keys[best] = huge;
                    }
                    int kNew = selIdx.Length;

                    int allocK = math.max(kNew, 1);
                    var Zsel = new floatMxN(d, allocK, Allocator.Temp, false);
                    var Ntheta = new floatMxN(d, d, Allocator.Temp, false);
                    var evTmp = new floatN(d);
                    var Vtmp = new floatMxN(d, d, Allocator.Temp, false);

                    bool eigOk = kNew > 0;
                    for (int sIt = 0; sIt < kNew && eigOk; sIt++)
                    {
                        int idx = selIdx[sIt];
                        float th = evReal[idx];
                        for (int ai = 0; ai < d; ai++)
                            for (int bi = 0; bi < d; bi++)
                                Ntheta[ai, bi] = Fmat[ai, bi] - th * (Gmat[ai, bi] + Gmat[bi, ai]) + th * th * Pgram[ai, bi];

                        var symInfo = Eigen.symmetricInPlace(ref Ntheta, ref evTmp, ref Vtmp);
                        if (symInfo.status != IterativeSolveStatus.Converged) { eigOk = false; break; }
                        for (int r = 0; r < d; r++) Zsel[r, sIt] = Vtmp[r, d - 1];
                    }

                    if (eigOk && kNew > 0)
                    {
                        var Unew = new UnsafeList<floatN>(kNew, Allocator.Temp);
                        var AUraw = new floatMxN(n, kNew, Allocator.Temp, false);

                        for (int sIt = 0; sIt < kNew; sIt++)
                        {
                            var ucol = new floatN(n);
                            var aucol = new floatN(n);
                            for (int l = 0; l < d; l++)
                            {
                                float zl = Zsel[l, sIt];
                                floatN Pl = l < kcurAtEntry ? U[l] : (flexible ? Zv[l - kcurAtEntry] : V[l - kcurAtEntry]);
                                floatN APl = l < kcurAtEntry ? AU[l] : AV[l - kcurAtEntry];
                                ucol.addScaledInPlace(zl, Pl);
                                aucol.addScaledInPlace(zl, APl);
                            }
                            Unew.Add(ucol);
                            for (int r = 0; r < n; r++) AUraw[r, sIt] = aucol[r];
                            aucol.Dispose();
                        }

                        var Rnew = new floatMxN(kNew, kNew, Allocator.Temp, false);
                        QR.decompInPlace(ref AUraw, ref Rnew);

                        float rGuard = Consts.floatEpsilon * (float)100 * (math.abs(Rnew[0, 0]) + (float)1);
                        int kSafe = 0;
                        while (kSafe < kNew && math.abs(Rnew[kSafe, kSafe]) > rGuard) kSafe++;

                        if (kSafe > 0)
                        {
                            for (int i = 0; i < kSafe; i++)
                            {
                                U[i].CopyFrom(Unew[i]);
                                for (int r = 0; r < n; r++) C[i][r] = AUraw[r, i];
                                for (int l = 0; l < kSafe; l++) Ru[i, l] = i <= l ? Rnew[i, l] : (float)0;
                            }
                            kcur = kSafe;
                        }

                        Rnew.Dispose();
                        AUraw.Dispose();
                        for (int sIt = 0; sIt < kNew; sIt++) Unew[sIt].Dispose();
                        Unew.Dispose();
                    }

                    Vtmp.Dispose(); evTmp.Dispose(); Ntheta.Dispose(); Zsel.Dispose();
                    selIdx.Dispose(); keys.Dispose();
                    evImag.Dispose(); evReal.Dispose();
                    Xsol.Dispose(); Pgram.Dispose(); Gmat.Dispose(); Fmat.Dispose();
                    if (hadOldU)
                    {
                        for (int i = 0; i < kcurAtEntry; i++) AU[i].Dispose();
                        AU.Dispose();
                    }
                }
            }

            for (int i = 0; i <= m; i++) V[i].Dispose();
            V.Dispose();
            if (flexible) { for (int i = 0; i < m; i++) Zv[i].Dispose(); Zv.Dispose(); }
            if (recycling)
            {
                for (int i = 0; i < m; i++) AV[i].Dispose();
                AV.Dispose();
                for (int i = 0; i < recycle; i++) { U[i].Dispose(); C[i].Dispose(); }
                U.Dispose(); C.Dispose();
                Ru.Dispose(); Bmat.Dispose(); ctr.Dispose(); zproj.Dispose();
            }
            H.Dispose(); cs.Dispose(); sn.Dispose(); g.Dispose(); y.Dispose(); w.Dispose();

            var status = breakdown ? IterativeSolveStatus.Breakdown
                       : converged ? IterativeSolveStatus.Converged
                       : IterativeSolveStatus.MaxIterations;
            return MakeSolveInfo(status, total, resnorm);
        }

        /// <summary>
        /// Unpreconditioned GCRO-DR -- forwards into the merged
        /// <see cref="gcrodr{TOp, TPre}(in TOp, in TPre, in floatN, ref floatN, int, int, int, float)"/>
        /// with the identity preconditioner.
        /// </summary>
        public static SolveInfo gcrodr<TOp>(in TOp A, in floatN b, ref floatN x, int restart, int recycle, int maxIter, float tol)
            where TOp : struct, IfloatLinearOperator
        {
            return gcrodr(in A, default(floatIdentityPreconditioner), in b, ref x, restart, recycle, maxIter, tol);
        }

        static int floatGcrodrDefaultRecycle(int restart) => math.min(10, math.max(0, restart - 1));

        /// <summary>GCRO-DR over a dense <see cref="floatMxN"/>. Forwards via floatDenseOperator.</summary>
        public static SolveInfo gcrodr(in floatMxN A, in floatN b, ref floatN x, int restart, int recycle, int maxIter, float tol)
            => gcrodr(new floatDenseOperator(in A), in b, ref x, restart, recycle, maxIter, tol);

        /// <summary>GCRO-DR over a dense matrix with defaults (restart = min(30, N), recycle = min(10, restart-1), maxIter = N, tol = sqrtEps).</summary>
        public static SolveInfo gcrodr(in floatMxN A, in floatN b, ref floatN x)
        {
            int r = math.min(30, A.M_Rows);
            return gcrodr(new floatDenseOperator(in A), in b, ref x, r, floatGcrodrDefaultRecycle(r), A.M_Rows, Consts.floatSqrtEps);
        }

